import { describe, expect, it } from "vitest";

import { setCargoLockPackageVersion } from "../scripts/lib/cargo-lock.mjs";

const LOCK = [
  "# This file is automatically @generated by Cargo.",
  "version = 4",
  "",
  "[[package]]",
  'name = "Panes"',
  'version = "0.65.1"',
  "dependencies = [",
  ' "anyhow",',
  "]",
  "",
  "[[package]]",
  'name = "anyhow"',
  'version = "0.65.1"',
  "",
].join("\n");

describe("setCargoLockPackageVersion", () => {
  it("rewrites only the named package's version", () => {
    const next = setCargoLockPackageVersion(LOCK, "Panes", "0.66.0");

    expect(next).toBe(LOCK.replace('name = "Panes"\nversion = "0.65.1"', 'name = "Panes"\nversion = "0.66.0"'));
    expect(next).toContain('name = "anyhow"\nversion = "0.65.1"');
  });

  it("keeps CRLF line endings", () => {
    const next = setCargoLockPackageVersion(LOCK.replaceAll("\n", "\r\n"), "Panes", "0.66.0");

    expect(next).toContain('name = "Panes"\r\nversion = "0.66.0"\r\n');
  });

  it("throws when the package is missing", () => {
    expect(() => setCargoLockPackageVersion(LOCK, "panes-missing", "1.0.0")).toThrow(
      "Could not find package panes-missing in Cargo.lock",
    );
  });
});
